S = "Hakeem Force Academy"
QS = [
(S, "What is the official capital of Indonesia?", ["Surabaya", "Jakarta", "Bandung", "Medan"], 1,
 "Jakarta is Indonesia's legal capital. A new capital, Nusantara in East Kalimantan, was planned by a 2022 law, but Jakarta stays the capital until a formal transfer decree is issued.",
 "Nusantara is now planned only as a political capital (target 2028), so candidates who wrote Nusantara in 2022 were anticipating a move that has not formally happened.", [3512, 46]),
(S, "In which year was the Al-Khalid main battle tank inducted into the Pakistan Army?", ["1991", "1996", "2001", "2008"], 2,
 "The Al-Khalid (MBT-2000), developed by Pakistan with Chinese cooperation, entered service with the Pakistan Army in 2001.",
 "An upgraded Al-Khalid-I was first handed over to the Armoured Corps in July 2020.", [2701]),
(S, "Which Chinese fighter jets did Pakistan Air Force formally induct in March 2022?", ["J-10C", "JF-17 Block I", "F-16 Block 52", "Mirage 2000"], 0,
 "The PAF commissioned its first six J-10C multirole fighters from China in March 2022.",
 "China's stealth fighter J-35 has been reported as a possible future PAF purchase, but no delivery has been officially confirmed.", [660]),
(S, "In which country did the first Industrial Revolution begin?", ["France", "Germany", "Great Britain", "United States"], 2,
 "The Industrial Revolution began in Great Britain in the second half of the 18th century, with steam power and mechanised textile production.",
 "James Watt's improved steam engine (1769 patent) was a key invention of this revolution.", [2582, 4315]),
(S, "How many sugar mills did Pakistan have at the time of independence in 1947?", ["2", "5", "12", "20"], 0,
 "Most colonial-era sugar mills lay on the Indian side of the border, and Pakistan inherited only two.",
 "The first new sugar mill after independence was set up at Tando Muhammad Khan in Sindh in 1961.", [2454, 4177]),
(S, "Complete the sentence: Smoking is injurious ___ health.", ["of", "for", "on", "to"], 3,
 "The adjective injurious is followed by the preposition to, so the correct phrase is injurious to health.",
 "The same pattern is used in harmful to, and detrimental to.", [1912, 1532]),
(S, "What is the sum of the interior angles of a triangle?", ["90 degrees", "180 degrees", "270 degrees", "360 degrees"], 1,
 "In Euclidean geometry the three interior angles of any triangle always add up to 180 degrees.",
 "The interior angles of a quadrilateral add up to 360 degrees.", [3956]),
(S, "Which cricketer scored 400 not out in a single Test innings?", ["Matthew Hayden", "Brian Lara", "Sachin Tendulkar", "Inzamam-ul-Haq"], 1,
 "Brian Lara of the West Indies scored 400 not out against England at Antigua in 2004.",
 "This remains the highest individual score in Test cricket; Lara also made 375 in 1994 and Hayden's 380 once held the record in between.", [4939, 5262, 5263]),
(S, "According to the Holy Quran and hadith, killing one innocent person is equal to what?", ["Killing a whole tribe only", "Killing the whole of humanity", "A minor sin", "Breaking a fast"], 1,
 "Surah Al-Maidah (5:32) says that whoever kills one innocent soul is as if he had killed all of mankind.",
 "The same verse says that saving one life is as if one had saved all of mankind.", [1670, 3226]),
(S, "What is the integral of ln x with respect to x?", ["x ln x - x + C", "1/x + C", "ln x - x + C", "x ln x + x + C"], 0,
 "Integrating by parts with u = ln x and dv = dx gives x ln x - integral of (x times 1/x) dx = x ln x - x + C.",
 "The derivative of ln x is 1/x.", [3652, 716]),
(S, "What is the integral of sin x with respect to x?", ["cos x + C", "-cos x + C", "-sin x + C", "tan x + C"], 1,
 "The derivative of cos x is -sin x, so the derivative of -cos x is sin x. Hence the integral of sin x is -cos x + C.",
 "The integral of cos x is sin x + C.", [3653]),
(S, "What is the integral of tan x with respect to x?", ["sec squared x + C", "ln |cos x| + C", "ln |sec x| + C", "-ln |sec x| + C"], 2,
 "Write tan x as sin x over cos x and put u = cos x; the integral becomes -ln |cos x| + C, which equals ln |sec x| + C.",
 "The derivative of tan x is sec squared x.", [3654]),
(S, "What is the meaning of the word interim?", ["Permanent", "Temporary or in the meantime", "Final", "Delayed forever"], 1,
 "Interim describes something provided or done for the time between two events, that is, temporary.",
 "An interim government rules only until a regular government is elected.", [1108, 3768]),
(S, "What is the antonym of interim?", ["Temporary", "Provisional", "Permanent", "Brief"], 2,
 "Interim means temporary, so its opposite is permanent.",
 "Provisional and temporary are synonyms of interim.", [3485]),
(S, "What does the adjective intimate mean?", ["Distant", "Close and familiar", "Hostile", "Unknown"], 1,
 "Intimate describes a very close, familiar relationship or a detailed, deep knowledge of something.",
 "Intimate can also be a verb meaning to hint at something indirectly, pronounced differently.", [3225, 3769, 1187]),
(S, "What is the antonym of intimate (adjective)?", ["Close", "Familiar", "Distant", "Dear"], 2,
 "Intimate means close and familiar, so the opposite is distant.",
 "Close, familiar and dear are synonyms of intimate.", [122, 3867]),
(S, "How far does Pakistan's territorial sea extend from its baseline?", ["6 nautical miles", "10 nautical miles", "12 nautical miles", "20 nautical miles"], 2,
 "Pakistan's Territorial Waters and Maritime Zones Act of 1976 fixed the territorial sea at 12 nautical miles, in line with international law.",
 "Pakistan's Exclusive Economic Zone extends up to 200 nautical miles.", [3423]),
(S, "On which date in 1933 was the name Pakistan first put forward by Choudhry Rahmat Ali in the pamphlet Now or Never?", ["28 January 1933", "23 March 1940", "14 August 1947", "30 December 1906"], 0,
 "Choudhry Rahmat Ali issued the pamphlet Now or Never on 28 January 1933 and proposed the name Pakistan in it.",
 "The Lahore Resolution came later, on 23 March 1940.", [2884]),
(S, "Which of the following is the multiplicative inverse form of the 2 by 2 matrix with entries a, b in the first row and c, d in the second row?", ["Matrix with d, -b in the first row and -c, a in the second row, multiplied by 1/(ad - bc)", "Matrix with a, c and b, d, multiplied by 1/(ad - bc)", "Matrix with -a, -b and -c, -d", "Matrix with d, b and c, a, multiplied by (ad - bc)"], 0,
 "For a 2 by 2 matrix, swap a and d, change the signs of b and c, and divide by the determinant ad - bc.",
 "The inverse exists only when the determinant is not zero.", [3656]),
(S, "The inverse of a square matrix exists only if what condition holds?", ["Its determinant is zero", "Its determinant is non-zero", "It has only one row", "All its entries are positive"], 1,
 "The inverse equals the adjoint divided by the determinant, so the determinant must not be zero; such a matrix is called non-singular.",
 "A matrix with zero determinant is called singular.", [3036]),
(S, "What is the additive inverse of the ordered pair (-a, -b)?", ["(-a, -b)", "(a, b)", "(1/a, 1/b)", "(a, -b)"], 1,
 "The additive inverse is the pair that gives (0, 0) when added. (-a, -b) + (a, b) = (0, 0), so the answer is (a, b).",
 "The additive identity of ordered pairs is (0, 0).", [3458]),
(S, "Inzamam-ul-Haq, one of Pakistan's best batsmen, played which sport for the Pakistan national team?", ["Hockey", "Squash", "Cricket", "Football"], 2,
 "Inzamam-ul-Haq played Test and One Day cricket for Pakistan from 1991 to 2007 and captained the team.",
 "He scored 8830 Test runs and 11701 ODI runs.", [892, 2777]),
(S, "What is the capital of Iran?", ["Isfahan", "Tabriz", "Tehran", "Mashhad"], 2,
 "Tehran is the capital and largest city of Iran.",
 "Iran lies to the west of Pakistan.", [3519]),
(S, "Is the number 5/7 rational or irrational?", ["Irrational", "Rational", "Neither rational nor real", "Imaginary"], 1,
 "A rational number can be written as p/q with integers p and q and q not zero. 5/7 has this form, so it is rational.",
 "The square root of 2 and pi are famous irrational numbers.", [987]),
(S, "Which type of number is 9/2?", ["Irrational only", "Imaginary", "Rational (and also real)", "Not a number"], 2,
 "9/2 is a ratio of two integers, so it is rational, and every rational number is also a real number.",
 "As a decimal, 9/2 equals 4.5, which terminates.", [2783]),
(S, "Is 22/7 a rational or an irrational number?", ["Irrational, because it is close to pi", "Rational, because it is a ratio of two integers", "Imaginary", "Neither"], 1,
 "22/7 is a fraction of two integers, so it is rational. It is only an approximation of pi, which is irrational.",
 "22/7 is about 3.142857 while pi is about 3.141593.", [1051]),
(S, "Whose mother was Hazrat Sara (AS)?", ["Hazrat Ismail (AS)", "Hazrat Ishaq (AS)", "Hazrat Yaqub (AS)", "Hazrat Yusuf (AS)"], 1,
 "Hazrat Sara (AS), wife of Hazrat Ibrahim (AS), was the mother of Hazrat Ishaq (AS).",
 "Hazrat Hajra (AS) was the mother of Hazrat Ismail (AS).", [3827, 1471]),
(S, "Hazrat Ismail (AS) is known by which title?", ["Khalilullah", "Kaleemullah", "Zabihullah", "Ruhullah"], 2,
 "Hazrat Ismail (AS) is called Zabihullah, the one offered for sacrifice, in the story of Hazrat Ibrahim's (AS) dream.",
 "Hazrat Ibrahim (AS) is called Khalilullah.", [2079]),
(S, "Which was the first ghazwa (expedition led personally by the Holy Prophet SAW) of Islam?", ["Badr", "Abwa (Waddan)", "Uhud", "Khandaq"], 1,
 "The first ghazwa, in Safar 2 AH, was Abwa, also called Waddan, in which the Prophet (SAW) himself went out but no fighting occurred.",
 "The first major battle of Islam was Badr in Ramadan 2 AH.", [80, 4958]),
(S, "Who is regarded as the first martyr of Islam?", ["Hazrat Hamza (RA)", "Hazrat Sumayyah (RA)", "Hazrat Ali (RA)", "Hazrat Musab bin Umair (RA)"], 1,
 "Hazrat Sumayyah (RA), mother of Hazrat Ammar (RA), was killed by Abu Jahl for her faith and is the first martyr of Islam.",
 "Some sources name Harith bin Abi Hala as the first male martyr, so sources differ.", [695]),
(S, "Which city was the capital of Pakistan before Islamabad?", ["Lahore", "Karachi", "Dhaka", "Peshawar"], 1,
 "Karachi was the first capital from 1947 until the capital moved to the new city of Islamabad in the 1960s, with Rawalpindi as interim seat.",
 "Islamabad was planned by the Greek architect Constantinos Doxiadis.", [648]),
(S, "Which battle was fought by the Muslims after the Battle of Badr, as the second major battle of Islam?", ["Khandaq", "Uhud", "Hunain", "Khyber"], 1,
 "Badr was fought in 2 AH and the Battle of Uhud followed in Shawwal 3 AH.",
 "Uhud is a mountain near Madinah.", [4171]),
(S, "Which is the 7th month of the Islamic (Hijri) calendar?", ["Shaban", "Rajab", "Jamadi-ul-Sani", "Ramadan"], 1,
 "The months are Muharram, Safar, Rabi-ul-Awwal, Rabi-ul-Sani, Jamadi-ul-Awwal, Jamadi-ul-Sani, then Rajab as the seventh.",
 "Rajab is one of the four sacred months, and Shab-e-Meraj is observed in it.", [3453]),
(S, "On which date is the International Day to Combat Islamophobia observed?", ["15 March", "15 April", "15 May", "15 June"], 0,
 "The UN General Assembly proclaimed 15 March as International Day to Combat Islamophobia in 2022, on a resolution moved by Pakistan on behalf of the OIC.",
 "15 March was chosen as the anniversary of the 2019 Christchurch mosque attacks.", [214, 1320]),
(S, "What is the capital of Israel as declared by Israel?", ["Tel Aviv", "Haifa", "Jerusalem", "Beersheba"], 2,
 "Israel declares Jerusalem as its capital, although most countries keep their embassies in Tel Aviv and the status of Jerusalem is disputed.",
 "Pakistan does not recognise Israel.", [3520]),
(S, "Who is the Prime Minister of Israel (as of October 2026, before the 27 October election)?", ["Naftali Bennett", "Yair Lapid", "Benjamin Netanyahu", "Benny Gantz"], 2,
 "Benjamin Netanyahu has led Israel's government since December 2022, and he is campaigning for the election due on 27 October 2026.",
 "Candidates in 2022 wrote Naftali Bennett, who was PM from June 2021 to June 2022, followed by Yair Lapid.", [454, 338]),
(S, "Who is the President of Israel?", ["Reuven Rivlin", "Isaac Herzog", "Shimon Peres", "Benjamin Netanyahu"], 1,
 "Isaac Herzog was elected the 11th President of Israel in June 2021 and is still in office.",
 "His predecessor was Reuven Rivlin, and the presidency is largely ceremonial.", [1416, 319]),
]
